import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundCloseForm{}
EMPTY = bytes.fromhex("")

GOLDENS = [
    pytest.param(v.ClientboundCloseFormPacket(), EMPTY, id=f"{v.__name__.rpartition('.')[2]}-empty") for v in VERSIONS
]


@pytest.mark.parametrize("version", VERSIONS)
def test_clientbound_close_form_is_packet_310(version):
    assert version.PACKETS[310] is version.ClientboundCloseFormPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_close_form_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_close_form_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS)
def test_clientbound_close_form_rejects_trailing_bytes(version):
    with pytest.raises(ValueError, match="trailing bytes"):
        version.ClientboundCloseFormPacket.from_bytes(b"\x7f\xff")
